  function openAnalysisStep(index) {
    const drawer = document.getElementById(`analysisStepDetail-${index}`);
    const card = document.querySelector(`[aria-controls="analysisStepDetail-${index}"]`);
    if (!drawer || !card) return;
    const isOpening = !drawer.classList.contains('active');
    drawer.classList.toggle('active', isOpening);
    card.setAttribute('aria-expanded', String(isOpening));
    card.querySelector('.flow-open').textContent = isOpening ? '收起 ↑' : '展开 ›';
    const previewArtifact = actualSteps[index].artifacts.find(([, path]) => window.__artifactPreviews?.[path]);
    if (isOpening && previewArtifact) previewArtifactResult(index, previewArtifact[1]);
  }

  function previewArtifactResult(index, path) {
    const preview = window.__artifactPreviews?.[path];
    const target = document.getElementById('artifactPreviewModalBody');
    const modal = document.getElementById('artifactPreviewModal');
    const title = document.getElementById('artifactPreviewModalTitle');
    const artifactLabel = actualSteps[index]?.artifacts.find(([, artifactPath]) => artifactPath === path)?.[0] || path;
    if (!preview || !target || !modal || !title) return;
    title.textContent = artifactLabel;
    if (preview.kind === 'json') {
      const items = preview.text.split(/\r?\n/).map((line) => {
        const depth = Math.max(0, Math.floor((line.match(/^\s*/)?.[0].length || 0) / 2));
        const content = line.trim().replace(/,$/, '');
        const indent = 9 + Math.min(depth, 4) * 12;
        if (!content || content === '{' || content === '}' || content === '[' || content === ']') return '';
        const matched = content.match(/^"([^"]+)"\s*:\s*(.+)$/);
        return matched ? `<li style="padding-left:${indent}px"><b>${escapeHtml(matched[1])}</b><span>${escapeHtml(matched[2])}</span></li>` : `<li class="json-structure" style="padding-left:${indent}px">${escapeHtml(content)}</li>`;
      }).filter(Boolean).join('');
      target.innerHTML = `<div class="artifact-preview-title">JSON 结果预览</div><ul class="artifact-json-list">${items}</ul>`;
      modal.classList.add('active');
      return;
    }
    const headers = preview.headers.map((header) => `<th>${escapeHtml(header)}</th>`).join('');
    const rows = preview.rows.map((row) => `<tr>${row.map((cell) => `<td>${escapeHtml(cell)}</td>`).join('')}</tr>`).join('');
    target.innerHTML = `<div class="artifact-preview-title">TSV 结果预览 <small>显示前 ${preview.shownRows} 行</small></div><div class="artifact-table-wrap"><table class="artifact-table"><thead><tr>${headers}</tr></thead><tbody>${rows}</tbody></table></div>`;
    modal.classList.add('active');
  }

  function closeArtifactPreview() { document.getElementById('artifactPreviewModal')?.classList.remove('active'); }

  function closeAnalysisStep(index) { const drawer = document.getElementById(`analysisStepDetail-${index}`); const card = document.querySelector(`[aria-controls="analysisStepDetail-${index}"]`); drawer?.classList.remove('active'); card?.setAttribute('aria-expanded', 'false'); if (card) card.querySelector('.flow-open').textContent = '展开 ›'; }

